{
  "name": "SPI串行接口控制模块",
  "name_en": "SPI Serial Interface Control Module",
  "manufacturer": "",
  "description": "一个非物理的通用SPI串行通信控制组件，用于在实验电子系统中通过寄存器硬件层配置移位长度、重复次数、等待周期和外部触发，并读写发送/接收数据缓冲区。它更像是FPGA或底层电子学中的SPI传输控制单元，而不是独立实验仪器。",
  "description_en": "A non-physical generic SPI serial communication control component used through a register-based hardware layer to configure shift length, repetition count, wait cycles, and external triggering, and to read/write transmit and receive data buffers in laboratory electronics. It appears to represent an SPI transfer control block in FPGA or low-level electronics rather than a standalone lab instrument.",
  "actions": [
    {
      "action_name": "auto-init",
      "description": "初始化SPI串行接口控制模块。",
      "description_en": "Initialize the SPI serial interface control module."
    },
    {
      "action_name": "auto-reset",
      "description": "软复位模块。",
      "description_en": "Soft reset the module."
    },
    {
      "action_name": "auto-start",
      "description": "开始移位传输数据序列。",
      "description_en": "Start shifting the data sequence."
    },
    {
      "action_name": "auto-set_size",
      "description": "设置数据移位的时钟周期数。",
      "description_en": "Set the number of clock cycles for data shifting."
    },
    {
      "action_name": "auto-get_size",
      "description": "获取数据移位的时钟周期数。",
      "description_en": "Get the number of clock cycles for data shifting."
    },
    {
      "action_name": "auto-set_wait",
      "description": "设置重复之间的等待时钟周期数。",
      "description_en": "Set the delay between repetitions in clock cycles."
    },
    {
      "action_name": "auto-get_wait",
      "description": "获取重复之间的等待时钟周期数。",
      "description_en": "Get the delay between repetitions in clock cycles."
    },
    {
      "action_name": "auto-set_repeat",
      "description": "设置序列重复次数。",
      "description_en": "Set the number of sequence repetitions."
    },
    {
      "action_name": "auto-get_repeat",
      "description": "获取序列重复次数。",
      "description_en": "Get the number of sequence repetitions."
    },
    {
      "action_name": "auto-set_en",
      "description": "设置外部启动信号使能状态。",
      "description_en": "Set the external start enable state."
    },
    {
      "action_name": "auto-get_en",
      "description": "获取外部启动信号使能状态。",
      "description_en": "Get the external start enable state."
    },
    {
      "action_name": "auto-is_done",
      "description": "获取传输或序列完成状态。",
      "description_en": "Get the transfer or sequence completion status."
    },
    {
      "action_name": "auto-is_ready",
      "description": "获取就绪状态。",
      "description_en": "Get the ready status."
    },
    {
      "action_name": "auto-get_mem_size",
      "description": "获取数据缓冲存储区大小。",
      "description_en": "Get the data buffer memory size."
    },
    {
      "action_name": "auto-set_data",
      "description": "设置发送数据流内容。",
      "description_en": "Set the outgoing data stream."
    },
    {
      "action_name": "auto-get_data",
      "description": "获取接收数据流内容。",
      "description_en": "Get the incoming data stream."
    }
  ],
  "tag_hints": [
    "SPI communication",
    "FPGA control block",
    "register hardware layer",
    "serial data shifting",
    "external trigger enable",
    "buffered data transfer",
    "digital electronics"
  ]
}

